def basis(x, j, kind):
    import itertools
    a = x[:, j]
    l = x[:, (j - 1) % 4]
    r = x[:, (j + 1) % 4]
    o = x[:, (j + 2) % 4]
    P = [np.ones(len(a)), l, a, r]
    if kind == 'linear':
        return np.column_stack(P)
    if kind == 'full_linear':
        return np.column_stack(P + [o])
    if kind == 'archive04':
        return np.column_stack(P + [a ** 3, a * r])
    if kind == 'full_quad':
        return np.column_stack(P + [o] + [x[:, i] * x[:, k] for (i, k) in itertools.combinations_with_replacement(range(4), 2)])
    if kind == 'full_cubic':
        return np.column_stack([np.ones(len(a))] + [np.prod(x[:, inds], axis=1) for d in (1, 2, 3) for inds in itertools.combinations_with_replacement(range(4), d)])
    if kind == 'own_poly':
        return np.column_stack(P + [o, a * a, a ** 3, a * l, a * r, a * o, a ** 5])
